initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Create Context Source Registration With Return with Response Status Code set to 201     and
        Delete Context Source Registration With Return with Response Status Code set to 204     and
        Retrieve Context Source Registration with Response Status Code set to ${response1.status_code}
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{registration_id}'
        method set to 'DELETE'
        Delete Context Source Registration with id set to '${registration_id}'
}
